window.STUDY=VOCAB.map(x=>({...x,kind:"word"}));function extra(kind,book,unit,title,s){s.split(";").forEach(x=>{let p=x.split("~");STUDY.push({kind,book,unit,title,en:p[0],cn:p[1]||""})})}
extra("phrase","七上","U1","You and Me","What's your name?~你叫什么名字？;My name is Peter.~我的名字叫彼得。;Where are you from?~你来自哪里？;I'm from China.~我来自中国。;How old are you?~你多大了？;I'm thirteen years old.~我十三岁。;Let's get to know each other.~让我们互相认识一下。;Would you like to be my friend?~你愿意做我的朋友吗？");
